#!/usr/bin/env python3

from __future__ import print_function

import datetime
import json

import click

import phe


def log(message, color="red"):
    click.echo(click.style(message, fg=color), err=True)


@click.group("pheutil")
@click.version_option(phe.__version__)
@click.option("--verbose", "-v", is_flag=True, help="Enables verbose mode.")
def cli(verbose=False):
    del verbose


@cli.command("genpkey")
@click.argument("output", type=click.File("w"))
@click.option("--keysize", type=int, default=2048, help="The keysize in bits. Defaults to 2048")
@click.option("--id", "key_id", type=str, default=None, help="Add an identifying comment to the key")
def generate_keypair(keysize, key_id, output):
    log("Generating a paillier keypair with keysize of {}".format(keysize))
    pub, priv = phe.generate_paillier_keypair(n_length=keysize)
    log("Keys generated")

    date = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    public_kid = key_id or "Paillier public key generated by pheutil on {}".format(date)
    private_kid = key_id or "Paillier private key generated by pheutil on {}".format(date)
    json.dump(priv.to_jwk(kid=private_kid, public_kid=public_kid), output)
    output.write("\n")
    log("Private key written to {}".format(output.name))


@cli.command()
@click.argument("input", type=click.File("r"))
@click.argument("output", type=click.File("w"))
def extract(input, output):
    log("Loading paillier keypair")
    private_key = json.load(input)
    error_msg = "Invalid private key"
    assert "pub" in private_key, error_msg
    assert private_key["kty"] == "DAJ", error_msg
    json.dump(private_key["pub"], output)
    output.write("\n")
    log("Public key written to {}".format(output.name))


@cli.command()
@click.argument("public", type=click.File("r"))
@click.argument("plaintext", type=str)
@click.option("--output", type=click.File("w"), help="Save to file instead of stdout")
def encrypt(public, plaintext, output=None):
    number = float(plaintext)
    log("Loading public key")
    public_key_data = json.load(public)
    public_key = load_public_key(public_key_data)
    log("Encrypting: {:+.16f}".format(number))
    encrypted = public_key.encrypt(number)
    print(serialise_encrypted(encrypted), file=output)


def serialise_encrypted(enc):
    if enc.exponent > -32:
        enc = enc.decrease_exponent_to(-32)
        assert enc.exponent == -32
    else:
        log("Exponent is less than -32")
    return json.dumps({"v": str(enc.ciphertext()), "e": enc.exponent})


@cli.command()
@click.argument("private", type=click.File("r"))
@click.argument("ciphertext", type=click.File("r"))
@click.option("--output", type=click.File("w"), help="Save to file instead of stdout")
def decrypt(private, ciphertext, output):
    private_key = load_private_key(json.load(private))
    log("Decrypting ciphertext")
    encrypted = load_encrypted_number(ciphertext, private_key.public_key)
    print(private_key.decrypt(encrypted), file=output)


@cli.command("addenc")
@click.argument("public", type=click.File("r"))
@click.argument("encrypted_a", type=click.File("r"))
@click.argument("encrypted_b", type=click.File("r"))
@click.option("--output", type=click.File("w"), help="Save to file instead of stdout")
def add_encrypted(public, encrypted_a, encrypted_b, output):
    log("Loading public key")
    public_key = load_public_key(json.load(public))
    log("Loading first encrypted number")
    enc_a = load_encrypted_number(encrypted_a, public_key)
    log("Loading second encrypted number")
    enc_b = load_encrypted_number(encrypted_b, public_key)
    log("Adding encrypted numbers together")
    print(serialise_encrypted(enc_a + enc_b), file=output)


@cli.command("add")
@click.argument("public", type=click.File("r"))
@click.argument("encrypted", type=click.File("r"))
@click.argument("plaintext", type=str)
@click.option("--output", type=click.File("w"), help="Save to file instead of stdout")
def add_encrypted_to_plaintext(public, encrypted, plaintext, output):
    log("Loading public key")
    public_key = load_public_key(json.load(public))
    log("Loading encrypted number")
    enc = load_encrypted_number(encrypted, public_key)
    log("Loading unencrypted number")
    number = float(plaintext)
    log("Adding")
    print(serialise_encrypted(enc + number), file=output)


@cli.command("multiply")
@click.argument("public", type=click.File("r"))
@click.argument("encrypted", type=click.File("r"))
@click.argument("plaintext", type=str)
@click.option("--output", type=click.File("w"), help="Save to file instead of stdout")
def multiply_encrypted_to_plaintext(public, encrypted, plaintext, output):
    log("Loading public key")
    public_key = load_public_key(json.load(public))
    log("Loading encrypted number")
    enc = load_encrypted_number(encrypted, public_key)
    log("Loading unencrypted number")
    number = float(plaintext)
    log("Multiplying")
    print(serialise_encrypted(enc * number), file=output)


def load_public_key(public_key_data):
    return phe.PaillierPublicKey.from_jwk(public_key_data)


def load_private_key(private_key_data):
    error_msg = "Invalid private key"
    assert "pub" in private_key_data, error_msg
    assert "key_ops" in private_key_data, error_msg
    assert "decrypt" in private_key_data["key_ops"], error_msg
    assert "p" in private_key_data, error_msg
    assert "q" in private_key_data, error_msg
    assert private_key_data["kty"] == "DAJ", error_msg
    return phe.PaillierPrivateKey.from_jwk(private_key_data)


def load_encrypted_number(enc_number_file, pub):
    ciphertext_data = json.load(enc_number_file)
    assert "v" in ciphertext_data
    assert "e" in ciphertext_data
    return phe.EncryptedNumber(pub, int(ciphertext_data["v"]), exponent=ciphertext_data["e"])


if __name__ == "__main__":
    cli()

