#!/usr/bin/env python3

import json
import numbers
import random

from phe.encoding import EncodedNumber
from phe.util import getprimeover, invert, isqrt, mulmod, powmod


DEFAULT_KEYSIZE = 3072


def generate_paillier_keypair(private_keyring=None, n_length=DEFAULT_KEYSIZE):
    p = q = n = None
    n_len = 0
    while n_len != n_length:
        p = getprimeover(n_length // 2)
        q = p
        while q == p:
            q = getprimeover(n_length // 2)
        n = p * q
        n_len = n.bit_length()

    public_key = PaillierPublicKey(n)
    private_key = PaillierPrivateKey(public_key, p, q)
    if private_keyring is not None:
        private_keyring.add(private_key)
    return public_key, private_key


class PaillierPublicKey(object):
    def __init__(self, n):
        self.g = int(n) + 1
        self.n = int(n)
        self.nsquare = self.n * self.n
        self.max_int = self.n // 3 - 1

    def __repr__(self):
        public_key_hash = hex(hash(self))[2:]
        return "<PaillierPublicKey {}>".format(public_key_hash[:10])

    def __eq__(self, other):
        return isinstance(other, PaillierPublicKey) and self.n == other.n

    def __hash__(self):
        return hash(self.n)

    def raw_encrypt(self, plaintext, r_value=None):
        if not isinstance(plaintext, numbers.Integral):
            raise TypeError("Expected int type plaintext but got: %s" % type(plaintext))
        plaintext = int(plaintext)

        if self.n - self.max_int <= plaintext < self.n:
            neg_plaintext = self.n - plaintext
            neg_ciphertext = (self.n * neg_plaintext + 1) % self.nsquare
            nude_ciphertext = invert(neg_ciphertext, self.nsquare)
        else:
            nude_ciphertext = (self.n * plaintext + 1) % self.nsquare

        r = r_value or self.get_random_lt_n()
        obfuscator = powmod(r, self.n, self.nsquare)
        return mulmod(nude_ciphertext, obfuscator, self.nsquare)

    def get_random_lt_n(self):
        return random.SystemRandom().randrange(1, self.n)

    def encrypt(self, value, precision=None, r_value=None):
        if isinstance(value, EncodedNumber):
            encoding = value
        else:
            encoding = EncodedNumber.encode(self, value, precision)
        return self.encrypt_encoded(encoding, r_value)

    def encrypt_encoded(self, encoding, r_value):
        if not isinstance(encoding, EncodedNumber):
            raise TypeError("encoding should be an EncodedNumber")
        obfuscator = r_value or 1
        ciphertext = self.raw_encrypt(encoding.encoding, r_value=obfuscator)
        encrypted_number = EncryptedNumber(self, ciphertext, encoding.exponent)
        if r_value is None:
            encrypted_number.obfuscate()
        return encrypted_number

    def to_jwk(self, kid=None):
        from phe.util import int_to_base64

        payload = {
            "kty": "DAJ",
            "alg": "PAI-GN1",
            "key_ops": ["encrypt"],
            "n": int_to_base64(self.n),
        }
        if kid is not None:
            payload["kid"] = kid
        return payload

    def to_json(self, kid=None):
        return json.dumps(self.to_jwk(kid=kid))

    @classmethod
    def from_jwk(cls, payload):
        from phe.util import base64_to_int

        if payload.get("kty") != "DAJ" or payload.get("alg") != "PAI-GN1":
            raise ValueError("Invalid public key")
        return cls(base64_to_int(payload["n"]))


class PaillierPrivateKey(object):
    def __init__(self, public_key, p, q):
        if not p * q == public_key.n:
            raise ValueError("given public key does not match the given p and q.")
        if p == q:
            raise ValueError("p and q have to be different")
        self.public_key = public_key
        if q < p:
            self.p = q
            self.q = p
        else:
            self.p = p
            self.q = q
        self.psquare = self.p * self.p
        self.qsquare = self.q * self.q
        self.p_inverse = invert(self.p, self.q)
        self.hp = self.h_function(self.p, self.psquare)
        self.hq = self.h_function(self.q, self.qsquare)

    @staticmethod
    def from_totient(public_key, totient):
        p_plus_q = public_key.n - totient + 1
        p_minus_q = isqrt(p_plus_q * p_plus_q - public_key.n * 4)
        q = (p_plus_q - p_minus_q) // 2
        p = p_plus_q - q
        if not p * q == public_key.n:
            raise ValueError("given public key and totient do not match.")
        return PaillierPrivateKey(public_key, p, q)

    def __repr__(self):
        return "<PaillierPrivateKey for {}>".format(repr(self.public_key))

    def __eq__(self, other):
        return isinstance(other, PaillierPrivateKey) and self.p == other.p and self.q == other.q

    def __hash__(self):
        return hash((self.p, self.q))

    def decrypt(self, encrypted_number):
        encoded = self.decrypt_encoded(encrypted_number)
        return encoded.decode()

    def decrypt_encoded(self, encrypted_number, Encoding=None):
        if not isinstance(encrypted_number, EncryptedNumber):
            raise TypeError(
                "Expected encrypted_number to be an EncryptedNumber not: %s"
                % type(encrypted_number)
            )
        if self.public_key != encrypted_number.public_key:
            raise ValueError("encrypted_number was encrypted against a different key!")

        Encoding = EncodedNumber if Encoding is None else Encoding
        encoded = self.raw_decrypt(encrypted_number.ciphertext(be_secure=False))
        return Encoding(self.public_key, encoded, encrypted_number.exponent)

    def raw_decrypt(self, ciphertext):
        if not isinstance(ciphertext, numbers.Integral):
            raise TypeError("Expected ciphertext to be an int, not: %s" % type(ciphertext))
        ciphertext = int(ciphertext)

        decrypt_to_p = mulmod(
            self.l_function(powmod(ciphertext, self.p - 1, self.psquare), self.p),
            self.hp,
            self.p,
        )
        decrypt_to_q = mulmod(
            self.l_function(powmod(ciphertext, self.q - 1, self.qsquare), self.q),
            self.hq,
            self.q,
        )
        return self.crt(decrypt_to_p, decrypt_to_q)

    def h_function(self, x, xsquare):
        return invert(
            self.l_function(powmod(self.public_key.g, x - 1, xsquare), x),
            x,
        )

    def l_function(self, x, p):
        return (x - 1) // p

    def crt(self, mp, mq):
        u = mulmod(mq - mp, self.p_inverse, self.q)
        return mp + (u * self.p)

    def to_jwk(self, kid=None, public_kid=None):
        from phe.util import int_to_base64

        payload = {
            "kty": "DAJ",
            "key_ops": ["decrypt"],
            "p": int_to_base64(self.p),
            "q": int_to_base64(self.q),
            "pub": self.public_key.to_jwk(kid=public_kid),
        }
        if kid is not None:
            payload["kid"] = kid
        return payload

    def to_json(self, kid=None, public_kid=None):
        return json.dumps(self.to_jwk(kid=kid, public_kid=public_kid))

    @classmethod
    def from_jwk(cls, payload):
        from phe.util import base64_to_int

        if payload.get("kty") != "DAJ" or "pub" not in payload:
            raise ValueError("Invalid private key")
        public_key = PaillierPublicKey.from_jwk(payload["pub"])
        return cls(
            public_key,
            base64_to_int(payload["p"]),
            base64_to_int(payload["q"]),
        )


class PaillierPrivateKeyring(object):
    def __init__(self, private_keys=None):
        self.__keyring = {}
        if private_keys is not None:
            for private_key in private_keys:
                self.add(private_key)

    def __getitem__(self, key):
        if isinstance(key, int):
            return list(self.__keyring.values())[key]
        return self.__keyring[key]

    def __len__(self):
        return len(self.__keyring)

    def __iter__(self):
        return iter(self.__keyring.values())

    def __eq__(self, other):
        return isinstance(other, PaillierPrivateKeyring) and self.__keyring == other.__keyring

    def __delitem__(self, public_key):
        del self.__keyring[public_key]

    def add(self, private_key):
        if not isinstance(private_key, PaillierPrivateKey):
            raise TypeError(
                "private_key should be of type PaillierPrivateKey, not %s"
                % type(private_key)
            )
        self.__keyring[private_key.public_key] = private_key

    def keys(self):
        return self.__keyring.keys()

    def values(self):
        return self.__keyring.values()

    def items(self):
        return self.__keyring.items()

    def decrypt(self, encrypted_number):
        private_key = self.__keyring[encrypted_number.public_key]
        return private_key.decrypt(encrypted_number)

    def to_json(self):
        return json.dumps([private_key.to_jwk() for private_key in self.__keyring.values()])

    @classmethod
    def from_json(cls, payload):
        data = json.loads(payload)
        return cls([PaillierPrivateKey.from_jwk(entry) for entry in data])

    def save(self, path):
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(self.to_json())

    @classmethod
    def load(cls, path):
        with open(path, "r", encoding="utf-8") as fh:
            return cls.from_json(fh.read())


Keyring = PaillierPrivateKeyring


class EncryptedNumber(object):
    def __init__(self, public_key, ciphertext, exponent=0):
        if not isinstance(public_key, PaillierPublicKey):
            raise TypeError("public_key should be a PaillierPublicKey")
        if not isinstance(ciphertext, numbers.Integral):
            raise TypeError("ciphertext should be an integer")
        self.public_key = public_key
        self.__ciphertext = int(ciphertext)
        self.exponent = int(exponent)
        self.__is_obfuscated = False

    def __repr__(self):
        return "<EncryptedNumber exponent={}>".format(self.exponent)

    def __add__(self, other):
        if isinstance(other, EncryptedNumber):
            return self._add_encrypted(other)
        if isinstance(other, EncodedNumber):
            return self._add_encoded(other)
        return self._add_scalar(other)

    def __radd__(self, other):
        return self.__add__(other)

    def __mul__(self, other):
        if isinstance(other, EncryptedNumber):
            raise NotImplementedError("Good luck with that...")
        encoding = other if isinstance(other, EncodedNumber) else EncodedNumber.encode(self.public_key, other)
        product = self._raw_mul(encoding.encoding)
        exponent = self.exponent + encoding.exponent
        return EncryptedNumber(self.public_key, product, exponent)

    def __rmul__(self, other):
        return self.__mul__(other)

    def __sub__(self, other):
        return self + (other * -1)

    def __rsub__(self, other):
        return other + (self * -1)

    def __truediv__(self, scalar):
        return self.__mul__(1 / scalar)

    def __neg__(self):
        return self * -1

    def ciphertext(self, be_secure=True):
        if be_secure and not self.__is_obfuscated:
            self.obfuscate()
        return self.__ciphertext

    def decrease_exponent_to(self, new_exp):
        if new_exp > self.exponent:
            raise ValueError(
                "New exponent %i should be more negative than old exponent %i"
                % (new_exp, self.exponent)
            )
        multiplied = self * pow(EncodedNumber.BASE, self.exponent - new_exp)
        multiplied.exponent = new_exp
        return multiplied

    def obfuscate(self):
        r = self.public_key.get_random_lt_n()
        r_pow_n = powmod(r, self.public_key.n, self.public_key.nsquare)
        self.__ciphertext = mulmod(self.__ciphertext, r_pow_n, self.public_key.nsquare)
        self.__is_obfuscated = True

    def _add_scalar(self, scalar):
        encoded = EncodedNumber.encode(
            self.public_key, scalar, max_exponent=self.exponent
        )
        return self._add_encoded(encoded)

    def _add_encoded(self, encoded):
        if self.public_key != encoded.public_key:
            raise ValueError("Attempted to add numbers encoded against different public keys!")

        a, b = self, encoded
        if a.exponent > b.exponent:
            a = self.decrease_exponent_to(b.exponent)
        elif a.exponent < b.exponent:
            b = b.decrease_exponent_to(a.exponent)

        encrypted_scalar = a.public_key.raw_encrypt(b.encoding, 1)
        sum_ciphertext = a._raw_add(a.ciphertext(False), encrypted_scalar)
        return EncryptedNumber(a.public_key, sum_ciphertext, a.exponent)

    def _add_encrypted(self, other):
        if self.public_key != other.public_key:
            raise ValueError("Attempted to add numbers encrypted against different public keys!")

        a, b = self, other
        if a.exponent > b.exponent:
            a = self.decrease_exponent_to(b.exponent)
        elif a.exponent < b.exponent:
            b = b.decrease_exponent_to(a.exponent)

        sum_ciphertext = a._raw_add(a.ciphertext(False), b.ciphertext(False))
        return EncryptedNumber(a.public_key, sum_ciphertext, a.exponent)

    def _raw_add(self, e_a, e_b):
        return mulmod(e_a, e_b, self.public_key.nsquare)

    def _raw_mul(self, plaintext):
        if not isinstance(plaintext, numbers.Integral):
            raise TypeError("Expected ciphertext to be int, not %s" % type(plaintext))
        plaintext = int(plaintext)

        if plaintext < 0 or plaintext >= self.public_key.n:
            raise ValueError("Scalar out of bounds: %i" % plaintext)

        if self.public_key.n - self.public_key.max_int <= plaintext:
            neg_ciphertext = invert(self.ciphertext(False), self.public_key.nsquare)
            neg_scalar = self.public_key.n - plaintext
            return powmod(neg_ciphertext, neg_scalar, self.public_key.nsquare)
        return powmod(self.ciphertext(False), plaintext, self.public_key.nsquare)

    def to_json_dict(self):
        return {"v": str(self.ciphertext()), "e": self.exponent}

    def to_json(self):
        return json.dumps(self.to_json_dict())

    @classmethod
    def from_json_dict(cls, public_key, payload):
        return cls(public_key, int(payload["v"]), exponent=payload["e"])

    @classmethod
    def from_json(cls, public_key, payload):
        return cls.from_json_dict(public_key, json.loads(payload))

