import unittest

import numpy as np

from phe import paillier


class MathTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.public_key, cls.private_key = paillier.generate_paillier_keypair(n_length=256)
        cls.vec_a = [0.3, 1.7, 6857.6, 1e-6]
        cls.vec_b = [-68, 1.8, 34, 1.5e6]
        cls.enc_a = [cls.public_key.encrypt(x) for x in cls.vec_a]
        cls.enc_b = [cls.public_key.encrypt(x) for x in cls.vec_b]

    def test_mean(self):
        encrypted_mean = np.mean(self.enc_a)
        self.assertAlmostEqual(self.private_key.decrypt(encrypted_mean), np.mean(self.vec_a))

    def test_dot(self):
        encrypted_dot = np.dot(self.enc_b, self.vec_a)
        self.assertAlmostEqual(self.private_key.decrypt(encrypted_dot), np.dot(self.vec_b, self.vec_a))


if __name__ == "__main__":
    unittest.main()

